from text_to_sql import generate_sql, validate_sql, execute_sql


TEST_CASES = [
    "Which products sold the most?",
    "Which country has the most customers?",
    "What is the total revenue generated by each product category?",
    "How many customers are there?",
    "How many orders are completed?",
    "What are the 5 most expensive products?",
    "How many orders does each customer have?",
    "What is the total quantity of products sold?",
    "Which products have never been ordered?",
    "What is the average product price?",
]


def evaluate():

    passed = 0
    failed = 0

    print("\nRunning Text-to-SQL evaluation...\n")

    for i, question in enumerate(TEST_CASES, 1):

        print(f"{i}. {question}")

        try:
            sql = generate_sql(question)

            is_valid, message = validate_sql(sql)

            if not is_valid:
                print("❌ FAIL - Invalid SQL")
                print(message)
                failed += 1
                continue

            execute_sql(sql)

            print("✅ PASS")
            print(f"SQL: {sql}")

            passed += 1

        except Exception as e:

            print("❌ FAIL")
            print(f"Error: {e}")

            failed += 1

        print()

    total = passed + failed
    accuracy = (passed / total) * 100 if total else 0

    print("=" * 40)
    print(f"Passed: {passed}/{total}")
    print(f"Failed: {failed}/{total}")
    print(f"Execution Accuracy: {accuracy:.1f}%")
    print("=" * 40)


if __name__ == "__main__":
    evaluate()